CREATE OR REPLACE FUNCTION ST_GeomFromText(geom_text text) RETURNS text LANGUAGE sql IMMUTABLE AS 'SELECT geom_text;';

DROP TABLE IF EXISTS "booking" CASCADE;
DROP TABLE IF EXISTS "flight" CASCADE;
DROP TABLE IF EXISTS "flightschedule" CASCADE;
DROP TABLE IF EXISTS "passengerdetails" CASCADE;
DROP TABLE IF EXISTS "passenger" CASCADE;
DROP TABLE IF EXISTS "employee" CASCADE;
DROP TABLE IF EXISTS "airplane" CASCADE;
DROP TABLE IF EXISTS "airplane_type" CASCADE;
DROP TABLE IF EXISTS "airline" CASCADE;
DROP TABLE IF EXISTS "airport_geo" CASCADE;
DROP TABLE IF EXISTS "airport" CASCADE;
DROP TABLE IF EXISTS "weatherdata" CASCADE;

CREATE TABLE "airport" (
    "airport_id" INT PRIMARY KEY,
    "iata" VARCHAR(3),
    "icao" VARCHAR(4) NOT NULL UNIQUE,
    "name" VARCHAR(100) NOT NULL
);

CREATE TABLE "airport_geo" (
    "airport_id" INT PRIMARY KEY REFERENCES "airport"("airport_id") ON DELETE CASCADE,
    "name" VARCHAR(100) NOT NULL,
    "city" VARCHAR(100),
    "country" VARCHAR(100),
    "latitude" NUMERIC(11, 8),
    "longitude" NUMERIC(11, 8),
    "geolocation" TEXT
);

CREATE TABLE "airline" (
    "airline_id" INT PRIMARY KEY,
    "iata" VARCHAR(3) NOT NULL,
    "airlinename" VARCHAR(100),
    "base_airport" INT REFERENCES "airport"("airport_id")
);

CREATE TABLE "airplane_type" (
    "type_id" INT PRIMARY KEY,
    "identifier" VARCHAR(100),
    "description" TEXT
);

CREATE TABLE "airplane" (
    "airplane_id" INT PRIMARY KEY,
    "capacity" INT NOT NULL,
    "type_id" INT NOT NULL REFERENCES "airplane_type"("type_id"),
    "airline_id" INT NOT NULL REFERENCES "airline"("airline_id")
);

CREATE TABLE "employee" (
    "employee_id" INT PRIMARY KEY,
    "firstname" VARCHAR(100),
    "lastname" VARCHAR(100),
    "birthdate" DATE,
    "sex" VARCHAR(1),
    "street" VARCHAR(150),
    "city" VARCHAR(100),
    "zip" VARCHAR(20),
    "country" VARCHAR(100),
    "emailaddress" VARCHAR(150),
    "telephoneno" VARCHAR(50),
    "salary" NUMERIC(10, 2),
    "department" VARCHAR(100),
    "username" VARCHAR(100),
    "password" VARCHAR(255)
);

CREATE TABLE "passenger" (
    "passenger_id" INT PRIMARY KEY,
    "passportno" VARCHAR(50),
    "firstname" VARCHAR(100),
    "lastname" VARCHAR(100)
);

CREATE TABLE "passengerdetails" (
    "passenger_id" INT PRIMARY KEY REFERENCES "passenger"("passenger_id") ON DELETE CASCADE,
    "birthdate" DATE,
    "sex" VARCHAR(1),
    "street" VARCHAR(150),
    "city" VARCHAR(100),
    "zip" VARCHAR(20),
    "country" VARCHAR(100),
    "emailaddress" VARCHAR(150),
    "telephoneno" VARCHAR(50)
);

CREATE TABLE "flightschedule" (
    "flightno" VARCHAR(20) PRIMARY KEY,
    "from" INT NOT NULL REFERENCES "airport"("airport_id"),
    "to" INT NOT NULL REFERENCES "airport"("airport_id"),
    "departure" TIME NOT NULL,
    "arrival" TIME NOT NULL,
    "airline_id" INT NOT NULL REFERENCES "airline"("airline_id"),
    "monday" SMALLINT DEFAULT 0,
    "tuesday" SMALLINT DEFAULT 0,
    "wednesday" SMALLINT DEFAULT 0,
    "thursday" SMALLINT DEFAULT 0,
    "friday" SMALLINT DEFAULT 0,
    "saturday" SMALLINT DEFAULT 0,
    "sunday" SMALLINT DEFAULT 0
);

CREATE TABLE "flight" (
    "flight_id" INT PRIMARY KEY,
    "flightno" VARCHAR(20),
    "from" INT NOT NULL REFERENCES "airport"("airport_id"),
    "to" INT NOT NULL REFERENCES "airport"("airport_id"),
    "departure" TIMESTAMP NOT NULL,
    "arrival" TIMESTAMP NOT NULL,
    "airline_id" INT NOT NULL REFERENCES "airline"("airline_id"),
    "airplane_id" INT NOT NULL REFERENCES "airplane"("airplane_id")
);

CREATE TABLE "booking" (
    "booking_id" INT PRIMARY KEY,
    "flight_id" INT NOT NULL REFERENCES "flight"("flight_id"),
    "seat" VARCHAR(10),
    "passenger_id" INT NOT NULL REFERENCES "passenger"("passenger_id"),
    "price" NUMERIC(10, 2)
);

CREATE TABLE "weatherdata" (
    "log_date" DATE NOT NULL,
    "time" TIME NOT NULL,
    "station" INT NOT NULL,
    "temp" NUMERIC(5, 2),
    "humidity" NUMERIC(5, 2),
    "airpressure" NUMERIC(7, 2),
    "wind" NUMERIC(6, 2),
    "weather" VARCHAR(100),
    "winddirection" INT,
    PRIMARY KEY ("log_date", "time", "station")
);





SET session_replication_role = 'replica';

DELETE FROM "booking";
DELETE FROM "flight";
DELETE FROM "flightschedule";
DELETE FROM "passengerdetails";
DELETE FROM "passenger";
DELETE FROM "employee";
DELETE FROM "airplane";
DELETE FROM "airplane_type";
DELETE FROM "airline";
DELETE FROM "airport_geo";
DELETE FROM "airport";
DELETE FROM "weatherdata";

